"""Small command-line parser with the program's observed argument grammar."""
import sys
import re
from helptext import LONG_HELP, SHORT_HELP

NAMES = '''from-file from-code from-image from-clipboard output silent execute skip range code-font-family code-theme has-breadcrumbs has-line-number breadcrumbs-separator breadcrumbs-font-family breadcrumbs-color start-line-number line-number-color delete-line delete-line-color add-line add-line-color highlight-range relative-highlight-range highlight-range-color raw-highlight-lines language file-path watermark watermark-font-family watermark-color shadow-radius shadow-color mac-window-bar has-border border-color margin-x margin-y title scale-factor title-font-family title-color background type config help version'''.split()
SHORT = dict(zip('fcioed alwhV'.replace(' ', ''), ['from-file','from-code','from-image','output','execute','delete-line','add-line','language','watermark','help','version']))
FLAGS = set('from-clipboard silent skip has-line-number relative-highlight-range has-border help version'.split())
OPTIONAL = {'from-code': 'Code', 'from-image': 'Image'}
MULTI = {'execute', 'delete-line', 'add-line'}
ENUMS = {'has-breadcrumbs':['true','false'], 'mac-window-bar':['true','false'], 'type':['ascii','image']}
FLOATS = {'margin-x','margin-y','shadow-radius'}
INTS = {'scale-factor':255, 'start-line-number':4294967295}
DEFAULTS = {'has-breadcrumbs':False, 'line-number-color':'#495162','delete-line-color':'#ff6b6b30','add-line-color':'#2ecc7130','highlight-range-color':'#ffffff10','border-color':'#ffffff30','scale-factor':3,'type':'image'}
TAIL = "For more information, try '--help'.\n"
GENERIC_USAGE = 'codesnap [OPTIONS] --output <OUTPUT>'

class CLIError(Exception):
    def __init__(self, text): self.text = text

def display(n):
    if n in FLAGS: return '--'+n
    if n in OPTIONAL: return '--'+n+' [<'+OPTIONAL[n]+'>]'
    return '--'+n+' <'+n.upper().replace('-','_')+'>'+('...' if n in MULTI else '')

def usage(selected):
    # Required options lead the usage; other options retain their occurrence order.
    ns=['output']+[n for n in selected if n!='output']
    return 'codesnap '+' '.join(display(n) for n in dict.fromkeys(ns))

def error(msg, use=None):
    raise CLIError('error: '+msg+'\n\n'+(('Usage: '+use+'\n\n') if use else '')+TAIL)

def similarity(a,b):
    # Jaro similarity, including the usual prefix adjustment for option spelling.
    if a==b:return 1.0
    d=max(len(a),len(b))//2-1
    ma=[False]*len(a); mb=[False]*len(b)
    for i,ch in enumerate(a):
        for j in range(max(0,i-d), min(i+d+1,len(b))):
            if not mb[j] and ch==b[j]:ma[i]=True;mb[j]=True;break
    m=sum(ma)
    if not m:return 0
    aa=[c for c,x in zip(a,ma) if x];bb=[c for c,x in zip(b,mb) if x]
    t=sum(x!=y for x,y in zip(aa,bb))/2
    s=(m/len(a)+m/len(b)+(m-t)/m)/3
    if s>0.7:
        pre=0
        for x,y in zip(a,b):
            if x!=y or pre==4:break
            pre+=1
        s+=pre*.1*(1-s)
    return s

def unexpected(arg, selected, pending=None):
    suggest=None
    if arg.startswith('--'):
        ranked=sorted([(similarity(arg[2:].split('=')[0],n),i,n) for i,n in enumerate(NAMES)], reverse=True)
        if ranked and ranked[0][0]>.8:suggest=ranked[0][2]
    s="unexpected argument '"+arg+"' found"
    if suggest:
        s+="\n\n  tip: a similar argument exists: '--"+suggest+"'"
        error(s,usage(selected+[suggest]))
    error(s,GENERIC_USAGE)

def convert(n,v):
    if n in ENUMS:
        if v not in ENUMS[n]:
            msg="invalid value '"+v+"' for '"+display(n)+"'\n  [possible values: "+', '.join(ENUMS[n])+']'
            # Boolean parsing intentionally doesn't offer fuzzy matches.
            if n=='type':
                ranked=sorted([(similarity(v,x),x) for x in ENUMS[n]],reverse=True)
                if ranked[0][0]>.8:msg+="\n\n  tip: a similar value exists: '"+ranked[0][1]+"'"
            error(msg)
        return (v=='true') if n!='type' else v
    detail=None
    if n in FLOATS:
        if v.strip()!=v or '_' in v or not re.fullmatch(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)',v,re.I):
            detail='invalid float literal'
        else:
            try: return float(v)
            except ValueError:detail='invalid float literal'
    if n in INTS:
        if not v:detail='cannot parse integer from empty string'
        elif not re.fullmatch(r'[+-]?[0-9]+',v):detail='invalid digit found in string'
        else:
            x=int(v)
            if x>9223372036854775807:detail='number too large to fit in target type'
            elif x< -9223372036854775808:detail='number too small to fit in target type'
            elif not 0<=x<=INTS[n]:detail=f'{x} is not in 0..={INTS[n]}'
            else:return x
    if detail is not None:error(f"invalid value '{v}' for '{display(n)}': {detail}")
    return v

def parse(argv):
    result=dict(DEFAULTS);selected=[];i=0
    while i<len(argv):
        arg=argv[i];i+=1;attached=None;islong=False
        if arg=='--':
            if i<len(argv):unexpected(argv[i],selected)
            break
        if arg.startswith('--'):
            islong=True
            ns=arg[2:].split('=',1);name=ns[0]
            if len(ns)==2:attached=ns[1]
            if name not in NAMES:unexpected('--'+name,selected)
        elif len(arg)>1 and arg[0]=='-':
            c=arg[1]
            if c not in SHORT:unexpected('-'+c,selected)
            name=SHORT[c]
            if len(arg)>2:
                if name in FLAGS:argv=argv[:i]+['-'+arg[2:]]+argv[i:]
                else:attached=arg[2:];attached=attached[1:] if attached.startswith('=') else attached
        else:unexpected(arg,selected)
        if name in selected and name not in MULTI:error(f"the argument '{display(name)}' cannot be used multiple times", GENERIC_USAGE)
        if name in FLAGS:
            if attached is not None:error(f"unexpected value '{attached}' for '{display(name)}' found; no more were expected",usage(selected+[name]))
            if name=='help':print(LONG_HELP if islong else SHORT_HELP,end='');raise SystemExit(0)
            if name=='version':print('codesnap-cli 0.13.1');raise SystemExit(0)
            result[name]=True
        else:
            values=[]
            if attached is not None:values.append(attached)
            while i<len(argv) and (argv[i]=='-' or not argv[i].startswith('-')) and (not values or name in MULTI):
                values.append(argv[i]);i+=1
            if not values:
                if name in OPTIONAL:result[name]=None
                else:
                    # An unrecognised negative-looking argument is diagnosed before a missing value.
                    if i<len(argv) and argv[i].startswith('-') and argv[i]!='--':
                        nxt=argv[i];known=(nxt[2:].split('=')[0] in NAMES) if nxt.startswith('--') else (len(nxt)>1 and nxt[1] in SHORT)
                        if not known:unexpected(nxt if nxt.startswith('--') else nxt[:2],selected,name)
                    extra='\n  [possible values: '+', '.join(ENUMS[name])+']' if name in ENUMS else ''
                    error(f"a value is required for '{display(name)}' but none was supplied"+extra)
            elif name in MULTI:result.setdefault(name,[]).extend(convert(name,v) for v in values)
