            if not mb[j] and ch==b[j]:ma[i]=True;mb[j]=True;break
    m=sum(ma)
    if not m:return 0
    aa=[c for c,x in zip(a,ma) if x];bb=[c for c,x in zip(b,mb) if x]
    t=sum(x!=y for x,y in zip(aa,bb))/2
    s=(m/len(a)+m/len(b)+(m-t)/m)/3
