        node.children={k:x for (k,t,r),x in zip(schema,node.children)}
        return
    if not isinstance(v,dict):reader.fail('invalid type: '+typename(v)+', expected '+expected,node.end)
    known={k:t for k,t,r in schema}
    for k,n in node.children.items():
        if k in known:check(reader,n,known[k]);v[k]=n.value
