"""Code snapshot command-line application."""
import os
import sys
import re
import json
import copy
import base64
import subprocess
from pathlib import Path
from arguments import parse, CLIError
from configuration import DEFAULT, DataError, read_configuration, read_highlights

CLIPBOARD_ERROR='Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable'

class Panic(Exception):
    def __init__(self,message,source='core/src/utils/color.rs:32:13'):
        self.message=message;self.source=source

def log(level,text):
