    names={2:'No such file or directory',13:'Permission denied',21:'Is a directory',20:'Not a directory',28:'No space left on device',36:'File name too long',30:'Read-only file system',17:'File exists',24:'Too many open files',22:'Invalid argument',32:'Broken pipe'}
    n=getattr(e,'errno',None)
    return (names.get(n,getattr(e,'strerror',str(e)))+f' (os error {n})') if n else str(e)

