def unsigned(s):
    if s=='':raise DataError('cannot parse integer from empty string')
    if not re.fullmatch(r'\+?[0-9]+',s):raise DataError('invalid digit found in string')
    x=int(s)
    if x>4294967295:raise DataError('number too large to fit in target type')
    return x

def parse_range(value,max_end):
    parts=value.split(':')
    if len(parts)>2:raise DataError('Invalid range format')
    if len(parts)==1:
        start=end=unsigned(parts[0])
    elif parts==['','']:raise DataError('cannot parse integer from empty string')
    else:
        start=unsigned(parts[0]) if parts[0] else 1
        end=unsigned(parts[1]) if parts[1] else max_end
    return min(start,end),max(start,end)

