    text=text.replace('\r\n','\n').replace('\r','\n').replace('\t','  ').rstrip()
    lines=text.split('\n')
    indents=[len(x)-len(x.lstrip(' ')) for x in lines if x.strip()]
    cut=min(indents) if indents else 0
    return '\n'.join(x[cut:] if len(x)>=cut else '' for x in lines)

def load_config(args):
    if 'config' in args:
        return read_configuration(Path(args['config']).read_text(encoding='utf-8'))
    home=os.environ.get('HOME')
    if not home:
        import pwd
        home=pwd.getpwuid(os.getuid()).pw_dir
    p=Path(home)/'.config/codesnap/config.json'
    if not p.exists():
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_text(json.dumps(DEFAULT,indent=2,ensure_ascii=False),encoding='utf-8')
        log('INFO','Automated created config file at '+json.dumps(str(p),ensure_ascii=False))
    return read_configuration(p.read_text(encoding='utf-8'))

def config_for(args,cfg):
