    if user.get('background') is None:raise DataError('`background` must be initialized')
    s=copy.deepcopy(DEFAULT['snapshot_config'])
    # Fields omitted from an explicitly supplied snapshot use the library defaults.
    for k in ['theme','window','code_config','watermark','background']:
        if user.get(k) is not None:s[k]=copy.deepcopy(user[k])
    if user.get('watermark') is None:s['watermark']=None
    s['code_config'].setdefault('breadcrumbs',None)
    opts={
        'code-theme':('theme',),'code-font-family':('code_config','font_family'),
        'watermark':('watermark','content'),'watermark-font-family':('watermark','font_family'),'watermark-color':('watermark','color'),
        'shadow-radius':('window','shadow','radius'),'shadow-color':('window','shadow','color'),
        'mac-window-bar':('window','mac_window_bar'),'border-color':('window','border','color'),
        'margin-x':('window','margin','x'),'margin-y':('window','margin','y'),
        'title':('window','title_config','title'),'title-color':('window','title_config','color'),'title-font-family':('window','title_config','font_family'),
        'breadcrumbs-separator':('code_config','breadcrumbs','separator'),'breadcrumbs-color':('code_config','breadcrumbs','color'),'breadcrumbs-font-family':('code_config','breadcrumbs','font_family'),
        'has-breadcrumbs':('code_config','breadcrumbs','enable')
