        if opt not in args['_selected']:continue
        d=s;defaults=DEFAULT['snapshot_config']
        for part in path[:-1]:
            defaults=defaults[part]
            if d.get(part) is None:d[part]=copy.deepcopy(defaults)
            d=d[part]
        d[path[-1]]=args[opt]
    if args.get('has-border'):s['window']['border']['width']=1
    return s

