    file_path=args.get('file-path')
    if 'from-image' in args:
        data=sys.stdin.buffer.read() if args['from-image'] is None else args['from-image'].encode('utf-8')
        return None,data,file_path
    if 'from-file' in args:
        return Path(args['from-file']).read_bytes().decode('utf-8'),None,file_path or args['from-file']
    if 'from-code' in args:
        s=sys.stdin.buffer.read().decode('utf-8') if args['from-code'] is None else args['from-code']
        return s,None,file_path
    if 'execute' in args:
        command=' '.join(args['execute'])
        if args.get('skip'):s=command
        else:
            p=subprocess.run(command,shell=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            s=(p.stdout+p.stderr).decode('utf-8',errors='replace')
