    raise DataError('No code snippet provided')

def main(argv):
    args=parse(argv)
    cfg=load_config(args)
    code,image,file_path=get_input(args)
    lines=rust_lines(code if code is not None else '')
    line_count=max(1,len(lines))
    cr=parse_range(args['range'],line_count) if 'range' in args else (1,line_count)
    raw=read_highlights(args['raw-highlight-lines']) if 'raw-highlight-lines' in args else []
    highlights=[]
    for v in raw:
        start=v[0];end=v[0] if len(v)==2 else v[1]
        highlights.append([start,end,color(v[-1])])
    bounds=cr
    if args.get('relative-highlight-range') and 'range' in args:bounds=(1,(cr[1]-cr[0])&0xffffffff)
    for opt,copt in [('delete-line','delete-line-color'),('add-line','add-line-color'),('highlight-range','highlight-range-color')]:
        values=args.get(opt,[])
        if isinstance(values,str):values=[values]
        for value in values:
            hr=parse_range(value,bounds[1])
            if hr[0]<bounds[0]:raise DataError(f'The highlight start range should be greater than or equal to {bounds[0]}')
            if hr[1]>bounds[1]:raise DataError(f'The highlight end range should be less than or equal to {bounds[1]}')
            c=color(args[copt]);offset=(cr[0]-1) if args.get('relative-highlight-range') else 0
            highlights.append([hr[0]+offset,hr[1]+offset,c])
    if code is not None:
        if 'range' in args:
            code='\n'.join(lines[cr[0]-1:cr[1]]) if cr[0]>0 else ''
        code=clean_code(code)
    if args['scale-factor']<1:raise DataError('The scale factor must be greater than 1')
    snapshot=config_for(args,cfg)
    if args['type']=='ascii':
        if args['output']!='clipboard':log('WARN','ASCII snapshot only supports copying to clipboard');return
        raise DataError(CLIPBOARD_ERROR)
    if image is None:
        theme=snapshot.get('theme') or 'candy'
        if theme!='candy':raise DataError('Cannot find '+theme+' theme')
    from rendering import render, decode_png
    source_image=decode_png(image) if image is not None else None
    # Validate colors in the same draw order as their components.
    win=snapshot['window']
    color(win['shadow']['color'])
    color(win['border']['color'])
    title=win['title_config']
    if title.get('title') is not None:color(title['color'])
    if args.get('has-line-number'):color(args['line-number-color'])
    crumbs=snapshot['code_config'].get('breadcrumbs')
    if crumbs and crumbs.get('enable') and file_path:color(crumbs['color'])
    bg=snapshot['background']
    if isinstance(bg,str):color(bg)
    else:
        for stop in bg['stops']:color(stop['color'])
    wm=snapshot.get('watermark')
    if wm and win['margin']['y']>=82:color(wm['color'])
    out=args['output']
    if out=='clipboard':raise DataError(CLIPBOARD_ERROR)
    ext=Path(out).suffix
    if ext not in ('.png','.svg','.html'):raise DataError('Unsupported output format')
    png=render(code,source_image,snapshot,args,file_path,cr,highlights,color)
    if ext=='.png':data=png
    else:
        b64=base64.b64encode(png).decode('ascii')
        if ext=='.html':data=('<img src="data:image/png;base64,'+b64+'" />').encode()
        else:data=('<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"><image href="data:image/png;base64,'+b64+'"/></svg>').encode()
    Path(out).write_bytes(data)
    if not args.get('silent'):
        log('SUCCESS',f'Snapshot saved to {out} successful!')
        if cfg['print_eggs']:
            print(" _________________________________________\n< Today is a great day to share CodeSnap! >\n -----------------------------------------\n        \\\n         \\\n            _~^~^~_\n        \\) /  o o  \\ (/\n          '_   -   _'\n          / '-----' \\")

if __name__=='__main__':
    try:main(sys.argv[1:])
    except CLIError as e:sys.stderr.write(e.text);sys.exit(2)
    except DataError as e:log('ERROR',str(e));sys.exit(1)
    except (OSError,UnicodeError) as e:log('ERROR',io_message(e));sys.exit(1)
    except Panic as e:
        sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at {e.source}:\n{e.message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        sys.exit(101)
